-- Index nested-loop join chains driven by an index RANGE or a rowid
-- lookup (speedtest1's four-way join): every probe key must come from
-- the right outer column — the planner's row width for a range / rowid
-- driver once omitted its hidden rowid slot and probed t3.a for t3.b.
CREATE TABLE z1(a INTEGER, b INTEGER, c TEXT);
CREATE TABLE z2(a INTEGER UNIQUE, b INTEGER, c TEXT);
CREATE TABLE t3(a INTEGER UNIQUE, b INTEGER, c TEXT);
CREATE TABLE t4(a INTEGER UNIQUE, b INTEGER, c TEXT);
