/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 68 AND 76 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 68 AND 73 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
/*ordered*/ SELECT t3.c, z2.c, z1.a FROM t4, t3, z2, z1 WHERE t4.rowid = 68 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 3;
SELECT count(*), sum(z1.a) FROM z1, z2, t4 WHERE t4.a > 100 AND z2.a=t4.b AND z1.c=z2.c;
/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 55 AND 63 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 55 AND 60 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
/*ordered*/ SELECT t3.c, z2.c, z1.a FROM t4, t3, z2, z1 WHERE t4.rowid = 55 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 3;
SELECT count(*), sum(z1.a) FROM z1, z2, t4 WHERE t4.a > 100 AND z2.a=t4.b AND z1.c=z2.c;
/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 17 AND 25 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 17 AND 22 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
/*ordered*/ SELECT t3.c, z2.c, z1.a FROM t4, t3, z2, z1 WHERE t4.rowid = 17 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 3;
SELECT count(*), sum(z1.a) FROM z1, z2, t4 WHERE t4.a > 100 AND z2.a=t4.b AND z1.c=z2.c;
/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 47 AND 55 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 47 AND 52 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
/*ordered*/ SELECT t3.c, z2.c, z1.a FROM t4, t3, z2, z1 WHERE t4.rowid = 47 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 3;
SELECT count(*), sum(z1.a) FROM z1, z2, t4 WHERE t4.a > 100 AND z2.a=t4.b AND z1.c=z2.c;
/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 26 AND 34 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 26 AND 31 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
/*ordered*/ SELECT t3.c, z2.c, z1.a FROM t4, t3, z2, z1 WHERE t4.rowid = 26 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 3;
SELECT count(*), sum(z1.a) FROM z1, z2, t4 WHERE t4.a > 100 AND z2.a=t4.b AND z1.c=z2.c;
/*ordered*/ SELECT z1.a, z1.c, z2.a, t3.a, t4.a FROM z1, z2, t3, t4 WHERE t4.a BETWEEN 43 AND 51 AND t3.a=t4.b AND z2.a=t3.b AND z1.c=z2.c ORDER BY 1, 3, 4;
/*ordered*/ SELECT t3.c, z2.c FROM t4, t3, z2 WHERE t4.a BETWEEN 43 AND 48 AND t3.a=t4.b AND z2.a=t3.b ORDER BY 1, 2;
